import { copyFile, mkdir } from "node:fs/promises";

export type BootstrapConfig = { env: Record<string, string>; installer: string[]; prepare: string[]; verifier: string[]; ompArgs: string[]; marker: string };
export const A0_STAGE = "/tmp/soroi-a0";

async function run(argv: string[], cwd: string, env: Record<string, string | undefined>): Promise<number> {
	const child = Bun.spawn(argv, { cwd, env, stdin: "inherit", stdout: "inherit", stderr: "inherit" });
	return await child.exited;
}

/** Runs inside IMG-01, only after the parent observed the clean-HOME gate and sent its owned token. */
export async function bootstrap(config: BootstrapConfig): Promise<number> {
	const home = process.env.HOME;
	if (!home) throw new Error("IMG-01 did not supply HOME");
	const agentDir = `${home}/.omp/agent`;
	await mkdir(agentDir, { recursive: true });
	await copyFile(`${A0_STAGE}/models.yml`, `${agentDir}/models.yml`);
	await copyFile(`${A0_STAGE}/config.yml`, `${agentDir}/config.yml`);
	const env = { ...process.env, ...config.env, PI_CODING_AGENT_DIR: agentDir };
	await mkdir(`${A0_STAGE}/proof/sessions`, { recursive: true });
	await mkdir(`${A0_STAGE}/release`, { recursive: true });
	console.log(`${config.marker}:injected`);
	const unpacked = await run(["tar", "-xf", `${A0_STAGE}/release.tar`, "-C", `${A0_STAGE}/release`], A0_STAGE, env);
	if (unpacked !== 0) return unpacked;
	const installed = await run(config.installer, `${A0_STAGE}/release`, env);
	if (installed !== 0) return installed;
	console.log(`${config.marker}:installed`);
	const prepared = await run(config.prepare, `${A0_STAGE}/release`, env);
	if (prepared !== 0) return prepared;
	const launcher = `${home}/.local/bin/soroi`;
	const version = await run([launcher, "--version"], A0_STAGE, env);
	if (version !== 0) return version;
	console.log(`${config.marker}:prepared`);
	const tui = await run([launcher, "--session-dir", `${A0_STAGE}/proof/sessions`, ...config.ompArgs], `${A0_STAGE}/release`, env);
	if (tui !== 0) return tui;
	// DIST-02 owns the five category predicates and writes the D8 A0 Verdict under proof/.
	return await run(config.verifier, `${A0_STAGE}/release`, env);
}

if (import.meta.main) {
	const config: BootstrapConfig = await Bun.file(`${A0_STAGE}/input.json`).json();
	process.exitCode = await bootstrap(config);
}

